bounded_host_request.command:
python3 - <<'PY'
import json,subprocess,urllib.parse
out={}
for name in ('debug-ai-debug-ai-1','asteria-ab-baseline-forensic','astera-v8','astera-v8-evaluator'):
 p=subprocess.run(['docker','inspect',name],capture_output=True,text=True,timeout=12)
 if p.returncode:out[name]={'error':'NOT_PRESENT'};continue
 row=json.loads(p.stdout)[0]
 values=(row.get('Config') or {}).get('Env') or []
 routes={}
 for var in values:
  k,_,v=var.partition('=')
  if k.startswith(('DEBUG_AI_CORE_GATE_','AI_CORE_BASE_URL')) and k.endswith(('_URL','BASE_URL')):
   u=urllib.parse.urlsplit(v)
   routes[k]={'scheme':u.scheme,'host':u.hostname,'port':u.port}
 out[name]={'running':row['State']['Running'],'routes':routes}
body='AI_CORE_CONSUMER_ROUTE_ORIGINS_ONLY\n'+json.dumps(out,ensure_ascii=False,indent=2)
r=subprocess.run(['gh','api','-X','POST','repos/G-ACE-inc/server-core/issues/10/comments','--input','-','--jq','.html_url'],input=json.dumps({'body':body}),capture_output=True,text=True,timeout=25)
print('ROUTE_AUDIT_URL='+r.stdout.strip() if r.returncode==0 else 'FAIL')
raise SystemExit(r.returncode)
PY
